import{z as A,x as s,o as e,c as d,q as r,j as n,D as t,d as i,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Dilated Attention","description":"","frontmatter":{"title":"Dilated Attention","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dilated-attention.md","filePath":"llm/dilated-attention.md","lastUpdated":1791413859000}'),B={name:"llm/dilated-attention.md"};function p(m,a,h,D,_,c){const E=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="dilated-attention" tabindex="-1">Dilated Attention <a class="header-anchor" href="#dilated-attention" aria-label="Permalink to &quot;Dilated Attention&quot;">​</a></h1><div class="epigraph"><p>不必连着看完整个邻域；隔固定步长取点，用同样的边数覆盖更远的距离。</p><footer>—— Rewon Child 等, Sparse Transformer, 2019</footer></div><p>滑动窗口解决的是「只看近邻」，感受野仍要靠深度一层层爬。膨胀注意力改的是取样步长：窗口内不再连号，而是每隔 \\(r\\) 个标记连一条边，用同等预算够到更远。Child、Gray、Radford 与 Sutskever 2019 年的 Sparse Transformer 用跨步（strided）模式做这件事；Beltagy 等人 2020 年的 Longformer 把膨胀滑窗分给不同头。本篇只讲「步长」这一根轴，连续滑窗见 <a href="/llm/sliding-window-attention">Sliding Window Attention</a>，把局部与全局拼成一张图见 <a href="/llm/sparse-attention-patterns">BigBird / Longformer 稀疏模式</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>固定窗口 \\(w\\) 时，位置 \\(t\\) 的最远可见点是 \\(t-w+1\\)。若 \\(w\\) 受显存限制不能加大，远距离只能等深层接力，信号衰减。卷积网络用膨胀卷积在同样核大小下扩大感受野，注意力可以做类比：把可见集从连续带改成带孔的栅。形式上一层仍是 \\(O(n\\cdot |S|)\\)，\\(|S|\\) 是每个位置连接的键数量。膨胀把可见集写成步长为 \\(r\\) 的格点：</p> \\[\\mathcal{S}_r(t)=\\{t-ir \\mid i=0,1,\\ldots,w-1\\}\\cap\\{1,\\ldots,t\\} \\]<p>覆盖半径变成约 \\(w\\cdot r\\)，边数仍约为 \\(w\\)。</p><p><span class="marginnote">「感受野」是从卷积网络借来的词：指一个位置的信息能「看到」多远。代个数字：窗口 \\(w=8\\)、步长 \\(r=4\\) 时，位置 \\(t\\) 只连 8 条边——\\(t, t-4, t-8, \\ldots, t-28\\)，却直接够到约 32 步之外；同样 8 条边的密窗最远只到 \\(t-7\\)。边数一样，半径翻了约 4 倍，这就是膨胀的全部卖点。</span></p><p>代价立刻出现：孔里的标记本层完全看不见，局部句法可能被跳过。若所有头共用同一 \\(r\\)，会留下系统性盲区。因此膨胀几乎从不单独使用，而是与 \\(r=1\\) 的密窗、或多组不同 \\(r\\) 的头搭配。问题是设计一张「有孔但可覆盖」的图，而不是把注意力变成随机下采样。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="步长如何扩大感受野" tabindex="-1">步长如何扩大感受野 <a class="header-anchor" href="#步长如何扩大感受野" aria-label="Permalink to &quot;步长如何扩大感受野&quot;">​</a></h3><p>取步长 \\(r\\)，位置 \\(t\\) 连接 \\(j=t, t-r, t-2r,\\ldots\\)，直到超出窗口或序列。Child 等人的跨步稀疏沿序列维按固定周期取样，再与另一组沿另一因子分解的模式交替，使两层复合后能覆盖更大区块。单层的最远跳是 \\(r\\) 的倍数，复合后的覆盖取决于模式是否互素、是否在层间错开相位。<span class="marginnote">膨胀和池化不同。池化先聚合再注意，孔里的信息以压缩形式还在；膨胀是硬丢掉孔里的边，那些 token 只能等其他头或其他层来补。评测盲区时必须按「哪一类位置永远连不上」来查，而不是只看平均长度。</span></p><p>Longformer 的膨胀滑窗更接近卷积：在宽度 \\(w\\) 的窗里以 \\(r\\) 取样，并且允许不同头用不同 \\(r\\)。部分头负责密局部，部分头负责稀长程，参数量不变，图的并集更密。这比所有头同一 \\(r\\) 更不容易留下固定盲区。</p><h3 id="与滑窗的组合" tabindex="-1">与滑窗的组合 <a class="header-anchor" href="#与滑窗的组合" aria-label="Permalink to &quot;与滑窗的组合&quot;">​</a></h3><p>纯膨胀没有局部边，对相邻 token 的拷贝与括号匹配不友好。实务图几乎总是「密窗 ∪ 膨胀」。密窗保证 \\(r=1\\) 的近邻，膨胀提供跳跃边。层间还可以错开膨胀相位，使第 \\(\\ell\\) 层的孔被第 \\(\\ell+1\\) 层的边补上，类似奇偶层交错。微软 2023 年的 LongNet 把多组指数增长的膨胀率叠在一起，使覆盖随段长指数上升，而计算仍接近线性；其名字就叫 Dilated Attention，但思想与 2019 年的跨步稀疏一脉。</p>',15)),(e(),n(o,null,{default:t(()=>[l(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BD%8D%E7%BD%AE%20t%22%5D%20--%3E%20B%5B%22%E5%AF%86%E7%AA%97%20%E6%AD%A5%E9%95%BF%201%22%5D%0A%20%20A%20--%3E%20C%5B%22%E8%86%A8%E8%83%80%20%E6%AD%A5%E9%95%BF%20r%22%5D%0A%20%20A%20--%3E%20D%5B%22%E6%9B%B4%E5%A4%A7%E8%86%A8%E8%83%80%20%E6%AD%A5%E9%95%BF%202r%22%5D%0A%20%20B%20--%3E%20E%5B%22%E5%B1%80%E9%83%A8%E5%8F%A5%E6%B3%95%22%5D%0A%20%20C%20--%3E%20F%5B%22%E4%B8%AD%E8%B7%9D%E4%BE%9D%E8%B5%96%22%5D%0A%20%20D%20--%3E%20G%5B%22%E8%BF%9C%E8%B7%9D%E8%B7%B3%E8%B7%83%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>训练掩码必须写出并集。若实现时先做密窗再「随机跳」，与固定 \\(r\\) 的膨胀不是同一张图，也无法复现论文里对覆盖半径的分析。</p><h3 id="硬件上的不规则访存" tabindex="-1">硬件上的不规则访存 <a class="header-anchor" href="#硬件上的不规则访存" aria-label="Permalink to &quot;硬件上的不规则访存&quot;">​</a></h3><p>密窗是带状，FlashAttention 很好写。膨胀的索引是算术序列，表面上规则，但 \\(r\\) 与块大小不对齐时，GPU 上会变成跨步加载，缓存行浪费。\\(r\\) 取 2 的幂、并与内核 tile 对齐，比取 3、5 这类「理论覆盖更好」的奇数更常赢。这也是后来硬件对齐稀疏（如 NSA 的块选择）要解决的问题：逻辑上漂亮的膨胀，物理上可能比稍密一点的块稀疏更慢。</p><p>因果约束下，膨胀只能向左跳，不能跳到未来。相位若对所有位置相同，序列开头的可用键更少，开头附近的膨胀头会退化成更短的密连接。实现需要在边界把越界下标丢掉，而不是取模——取模会把末尾键绕到开头，破坏因果。<span class="marginnote">取模在卷积里常见，在因果注意力里是泄漏。一旦未来键绕到可见集，训练损失会虚低，生成却对不齐。边界检查应写成下标算术，而不是环形缓冲那套取模。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2>',5)),(e(),n(o,null,{default:t(()=>[l(E,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E4%BD%8D%E7%BD%AE%20t%EF%BC%9A%E5%8F%AF%E8%A7%81%E9%9B%86%E6%98%AF%E5%B8%A6%E5%AD%94%E6%A0%85%E6%A0%BC%22%5D%20--%3E%20K%7B%22%E5%85%B3%E9%94%AE%E9%94%AE%E8%90%BD%E5%9C%A8%E5%93%AA%EF%BC%9F%22%7D%0A%20%20K%20--%3E%7C%22%E6%81%B0%E5%9C%A8%E6%A0%85%E6%A0%BC%E7%82%B9%EF%BC%9At%E2%88%92r%2C%20t%E2%88%922r%E2%80%A6%22%7C%20HIT%5B%22%E4%B8%8E%E8%BF%91%E9%82%BB%E7%9B%B4%E6%8E%A5%E6%AF%94%E5%88%86%EF%BC%8C%E4%B8%80%E6%AD%A5%E5%A4%9F%E5%88%B0%E8%BF%9C%E5%A4%84%22%5D%0A%20%20K%20--%3E%7C%22%E8%90%BD%E5%9C%A8%E5%AD%94%E9%87%8C%22%7C%20MISS%5B%22%E6%9C%AC%E5%B1%82%E5%88%86%E6%95%B0%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20MISS%20--%3E%20ALT%5B%22%E7%AD%89%E5%85%B6%E4%BB%96%E5%A4%B4%EF%BC%9A%E4%B8%8D%E5%90%8C%20r%20%E7%9A%84%E6%A0%85%E6%A0%BC%E9%94%99%E5%BC%80%22%5D%0A%20%20ALT%20--%3E%20NEXT%5B%22%E6%88%96%E7%AD%89%E4%B8%8B%E4%B8%80%E5%B1%82%E7%9A%84%E8%BE%B9%E8%A1%A5%E4%B8%8A%22%5D%0A%20%20NEXT%20--%3E%20OK%5B%22%E4%BF%A1%E6%81%AF%E7%BB%8F%E4%B8%A4%E8%B7%B3%E5%88%B0%E8%BE%BE%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>注意力权重仍是可见集上的 softmax。膨胀改变的是竞争者名单：远距离的某个 token 若落在栅格上，可以和近邻直接比分；落在孔里，本层分数为零。信息几何上，膨胀边是捷径，缩短了依赖的层数。若任务的关键键恰好落在栅格上，膨胀会明显优于同预算的密窗；若关键键总在孔里，膨胀会系统性失败。多头多 \\(r\\) 的意义就是把栅格错开，使任意位置都有某个头能直接够到。</p><p><span class="marginnote">直觉类比：一队人手拉手只握住每隔 4 个的同伴——队伍「跨度」很大，但被跳过的人暂时脱队；如果旁边还有第二队按每隔 3 个握手，任何脱队的人都能在第二队里被握住。多头不同 \\(r\\) 就是让几队栅格互相错开、孔互不重叠，合起来才没有永远看不见的位置。</span></p><p>与线性注意力相比，膨胀仍是选择有限个原始 token 做 softmax，保留尖峰权重的能力；线性路线用核把所有位置揉进状态，尖峰更难。与随机稀疏相比，膨胀是确定性图，便于分析感受野，也便于把掩码写进内核，但缺少 BigBird 那种「随机边提高连通性」的理论备用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>膨胀对周期结构（诗行、表格列、固定帧率音视频）特别友好，因为栅格与数据周期可能对齐；对随机出现的针则不友好，除非 \\(r\\) 很小或头足够多。不要在针测上用单一 \\(r\\) 的膨胀当长上下文方案。另一边界是位置编码：RoPE 按真实下标旋转，膨胀边连接的是远距离下标，相对角度很大，可能落在旋转外推不稳的区域。这时失败看起来像「膨胀不行」，其实是位置外推，应与 <a href="/llm/position-extrapolation">位置插值与外推失败模式</a> 分开诊断。</p><p><span class="marginnote">为什么这步诊断重要：把位置编码问题误当成稀疏模式问题，会得出「膨胀注意力不行」的错误结论，白白换掉本来健康的方案。排查顺序应是先在密窗模型上测同一段长文本——若密窗同样崩，是位置外推的问题；只有密窗好、膨胀崩，才是栅格孔的锅。</span></p><p>工程上，若内核没有跨步掩码，膨胀会退化成物化稀疏掩码，二次空间又回来。能落地的膨胀，必须能在分块注意力里用下标算术跳过孔，而不是先算全矩阵再乘掩码。取舍建议：把 \\(r=1\\) 的滑窗当必选底盘；膨胀只加在少数头或少数层；\\(r\\) 选 2 的幂并对齐 tile。需要任意位置精确检索时，膨胀不如全局 token 或可学习选择。<span class="marginnote">膨胀的感受野数字很好看：步长 8、窗 512，半径一下子到四千。数字背后是孔。产品评测必须包含「答案落在孔里」的用例，否则会把纸面感受野当成真实长程。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>膨胀用步长 \\(r\\) 在边数不变时放大覆盖半径，代价是孔状盲区。</li><li>几乎必须与密窗、多 \\(r\\) 或多头相位错开联用，单独使用会留下周期空洞。</li><li>Child 2019 的跨步因子分解与 Longformer 的膨胀滑窗是同一思想的两种图。</li><li>GPU 上跨步加载可能比逻辑更密的块稀疏更慢，\\(r\\) 应对齐硬件。</li><li>因果下禁止取模绕回；RoPE 大跨度边要单独检查外推。</li><li>精确针测不是膨胀的主场，它更适合有结构的长程。</li><li>出处：Child et al., <em>Generating Long Sequences with Sparse Transformers</em>, 2019；Beltagy et al., <em>Longformer</em>, 2020；微软 LongNet / Dilated Attention, 2023。</li></ul>',9))])}const u=A(B,[["render",p]]);export{C as __pageData,u as default};
